python3 << 'PYTHON'
import json

with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_18/projects/schema-dag-extraction/artifacts/eval_exp1.json') as f:
    data = json.load(f)

# Get all count levels with their batch recalls
count_recalls = {}
for key, batch_result in data.items():
    if key.startswith('count_'):
        count = batch_result.get('count_key')
        if count not in count_recalls:
            count_recalls[count] = []
        # Calculate recall from the batch result
        if 'text_match_metrics' in batch_result:
            recall = batch_result['text_match_metrics'].get('recall')
            if recall is not None:
                count_recalls[count].append(recall)

# Print per-batch recalls for each count level
for count in sorted(count_recalls.keys(), key=lambda x: int(x.split('_')[1])):
    recalls = sorted(count_recalls[count])
    print(f"{count}: {recalls}")
    if recalls:
        print(f"  Mean: {sum(recalls)/len(recalls):.4f}, Std: {(sum((x - sum(recalls)/len(recalls))**2 for x in recalls)/len(recalls))**0.5:.4f}")
PYTHON

